{
  "name": "webtoapp-payment-proxy",
  "version": "1.0.0",
  "description": "Payment proxy for WebToApp - Routes payments through Vercel to Razorpay",
  "main": "index.js",
  "scripts": {
    "dev": "vercel dev",
    "deploy": "vercel --prod"
  },
  "dependencies": {
    "razorpay": "^2.9.4",
    "crypto": "^1.0.1"
  },
  "engines": {
    "node": ">=18.x"
  }
}

{
  "version": 2,
  "name": "webtoapp-payment-proxy",
  "builds": [
    {
      "src": "api/**/*.js",
      "use": "@vercel/node"
    }
  ],
  "routes": [
    {
      "src": "/api/(.*)",
      "dest": "/api/$1"
    }
  ],
  "headers": [
    {
      "source": "/api/(.*)",
      "headers": [
        {
          "key": "Access-Control-Allow-Origin",
          "value": "https://websitetoapp.app"
        },
        {
          "key": "Access-Control-Allow-Methods",
          "value": "GET, POST, PUT, DELETE, OPTIONS"
