  ArrowRight,
  Loader2,
  AlertTriangle,
  X,
  ExternalLink,
  FlaskConical,
  BookOpen,
  Zap,
  LayoutList,
  Users,
  RefreshCw,
  MapPinned,
  BarChart3,
  CreditCard,
  Star,
  Server,
  Contact,
  Activity,
  Play,
  Gift,
  MessageCircle,
  Palette,
  Bluetooth,
  FolderDown,
  CirclePlus,
  Wallet,
  Database,
  Lock,
  Power,
  PanelBottom,
  BellRing,
  Nfc,
} from 'lucide-react'
import { useWizardStore, type Platform } from '@/store/wizardStore'
import { appsApi } from '@/api/apps'
import { ordersApi, paymentsApi, plansApi } from '@/api/orders'
import { createRazorpayOrder, verifyRazorpayPayment } from '@/api/razorpay-proxy'
import type { Plan, NavigationItem } from '@/types'
import { formatPlanPrice, getUserCurrency } from '@/utils/format'

// ---------- Step 0: Basic Info ----------

const basicInfoSchema = z.object({
  name: z.string().min(1, 'App name is required').max(100),
  url: z.string().url('Please enter a valid URL'),
  package_name: z.string().optional(),
  description: z.string().max(500).optional(),
})

type BasicInfoData = z.infer<typeof basicInfoSchema>

// ---------- Feature definitions ----------

const FEATURES = [
  { key: 'push_notifications', label: 'Push Notifications', description: 'Send push notifications via Firebase', icon: Bell },
  { key: 'admob', label: 'AdMob Ads', description: 'Monetize with Google AdMob ads', icon: DollarSign },
  { key: 'biometric_auth', label: 'Biometric Auth', description: 'Fingerprint and face unlock', icon: Fingerprint },
  { key: 'deep_linking', label: 'Deep Linking', description: 'Handle deep links and URLs', icon: Link2 },
  { key: 'offline_mode', label: 'Offline Mode', description: 'Cache content for offline access', icon: WifiOff },
  { key: 'navigation_menu', label: 'Navigation Menu', description: 'Bottom nav or drawer menu', icon: Menu },
  { key: 'qr_scanner', label: 'QR Scanner', description: 'Built-in QR code scanner', icon: QrCode },
  { key: 'js_bridge', label: 'JS Bridge', description: 'JavaScript to native bridge', icon: Code2 },
  { key: 'screenshot_prevention', label: 'Screenshot Prevention', description: 'Block screenshots in app', icon: ShieldOff },
  { key: 'file_upload', label: 'File Upload', description: 'Support file uploads from device', icon: Upload },
  { key: 'location_services', label: 'Location Services', description: 'Access device GPS location', icon: MapPin },
  { key: 'camera_access', label: 'Camera Access', description: 'Access device camera', icon: Camera },
  { key: 'onboarding_screen', label: 'Onboarding Screen', description: 'Welcome screens for first-time users', icon: BookOpen },
  { key: 'app_shortcut', label: 'App Shortcut', description: 'Home screen quick action shortcuts', icon: Zap },
  { key: 'secondary_navigation', label: 'Secondary Navigation', description: 'Additional navigation options', icon: LayoutList },
  { key: 'social_login', label: 'Social Login', description: 'Sign in with social accounts', icon: Users },
  { key: 'in_app_update', label: 'In-App Update', description: 'Prompt users to update the app', icon: RefreshCw },
  { key: 'background_location', label: 'Background Location', description: 'Track location in background', icon: MapPinned },
  { key: 'facebook_app_events', label: 'Facebook App Events', description: 'Track events with Facebook SDK', icon: BarChart3 },
  { key: 'in_app_purchases', label: 'In-App Purchases', description: 'Sell digital goods in-app', icon: CreditCard },
  { key: 'in_app_review', label: 'In-App Review', description: 'Prompt users to rate the app', icon: Star },
  { key: 'background_service', label: 'Background Service', description: 'Run tasks in the background', icon: Server },
  { key: 'native_contacts', label: 'Native Contacts', description: 'Access device contacts', icon: Contact },
  { key: 'appsflyer', label: 'AppsFlyer', description: 'Attribution and analytics tracking', icon: Activity },
  { key: 'custom_media_player', label: 'Custom Media Player', description: 'Built-in audio/video player', icon: Play },
  { key: 'offer_card', label: 'Offer Card', description: 'Display promotional offer cards', icon: Gift },
  { key: 'intercom', label: 'Intercom', description: 'In-app customer messaging', icon: MessageCircle },
  { key: 'dynamic_app_icon', label: 'Dynamic App Icon', description: 'Change app icon dynamically', icon: Palette },
  { key: 'bluetooth_connectivity', label: 'Bluetooth Connectivity', description: 'Connect to Bluetooth devices', icon: Bluetooth },
  { key: 'download_file_manager', label: 'Download Manager', description: 'Manage file downloads in-app', icon: FolderDown },
  { key: 'floating_action_menu', label: 'Floating Action Menu', description: 'Floating action button with menu', icon: CirclePlus },
  { key: 'revenue_cat', label: 'Revenue Cat', description: 'Subscription management via RevenueCat', icon: Wallet },
  { key: 'native_datastore', label: 'Native Datastore', description: 'Local data storage on device', icon: Database },
  { key: 'passcode_lock', label: 'Passcode Lock', description: 'App lock with passcode', icon: Lock },
  { key: 'app_auto_launch', label: 'App Auto Launch', description: 'Launch app on device boot', icon: Power },
  { key: 'advanced_bottom_navigation', label: 'Advanced Bottom Nav', description: 'Enhanced bottom navigation bar', icon: PanelBottom },
  { key: 'firebase_notification', label: 'Firebase Notification', description: 'Firebase Cloud Messaging notifications', icon: BellRing },
  { key: 'tap_to_pay', label: 'Tap to Pay', description: 'NFC-based tap to pay support', icon: Nfc },
] as const

// ---------- Step indicator ----------

const STEP_LABELS = ['Basic Info', 'Visuals', 'Features', 'Advanced', 'Plan & Review']

function StepIndicator({ currentStep }: { currentStep: number }) {
  return (
    <div className="flex items-center justify-center mb-6 sm:mb-10 overflow-x-auto">
      {STEP_LABELS.map((label, idx) => (
        <div key={label} className="flex items-center">
          <div className="flex flex-col items-center">
            <div
              className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-xs sm:text-sm font-semibold border-2 transition-colors ${
                idx < currentStep
                  ? 'bg-blue-600 border-blue-600 text-white'
                  : idx === currentStep
                    ? 'border-blue-600 text-blue-600 bg-blue-50'
                    : 'border-gray-300 text-gray-400 bg-white'
              }`}
            >
              {idx < currentStep ? <Check className="w-4 h-4 sm:w-5 sm:h-5" /> : idx + 1}
            </div>
            <span
              className={`mt-1 sm:mt-1.5 text-[10px] sm:text-xs font-medium hidden sm:block ${
                idx <= currentStep ? 'text-blue-600' : 'text-gray-400'
              }`}
            >
              {label}
            </span>
          </div>
          {idx < STEP_LABELS.length - 1 && (
            <div
              className={`w-6 sm:w-16 h-0.5 mx-1 sm:mx-2 mb-2 sm:mb-5 ${
                idx < currentStep ? 'bg-blue-600' : 'bg-gray-300'
              }`}
            />
          )}
        </div>
      ))}
    </div>
  )
}

// ---------- Image Dropzone ----------

function ImageDropzone({
  label,
  preview,
  onDrop,
  hint,
}: {
  label: string
  preview: string | null
  onDrop: (files: File[]) => void
  hint: string
}) {
  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    accept: { 'image/*': [] },
    maxFiles: 1,
    onDrop,
  })

  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>
      <div
        {...getRootProps()}
        className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-colors ${
          isDragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-gray-400'
        }`}
      >
        <input {...getInputProps()} />
        {preview ? (
          <img src={preview} alt={label} className="mx-auto max-h-32 rounded-lg object-contain" />
        ) : (
          <div className="text-gray-500">
            <Upload className="w-8 h-8 mx-auto mb-2" />
            <p className="text-sm">Drop file here or click to upload</p>
            <p className="text-xs text-gray-400 mt-1">{hint}</p>
          </div>
        )}
      </div>
    </div>
  )
}

// ---------- Color Picker Section ----------

function ColorPickerField({
  label,
  color,
  onChange,
}: {
  label: string
  color: string
  onChange: (c: string) => void
}) {
  const [open, setOpen] = useState(false)

  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="flex items-center gap-3 border rounded-lg px-3 py-2 w-full hover:bg-gray-50"
      >
        <div className="w-8 h-8 rounded-md border" style={{ backgroundColor: color }} />
        <span className="text-sm font-mono">{color}</span>
      </button>
      {open && (
        <div className="mt-2">
          <HexColorPicker color={color} onChange={onChange} />
        </div>
      )}
    </div>
  )
}

// ---------- Phone Mockup ----------

function PhoneMockup({
  primaryColor,
  secondaryColor,
  statusBarColor,
  iconPreview,
  appName,
}: {
  primaryColor: string
  secondaryColor: string
  statusBarColor: string
  iconPreview: string | null
  appName: string
}) {
  return (
    <div className="flex justify-center">
      <div className="w-[220px] h-[440px] rounded-[2rem] border-4 border-gray-800 bg-white overflow-hidden shadow-xl relative">
        {/* Status bar */}
        <div className="h-7 flex items-center justify-center px-4" style={{ backgroundColor: statusBarColor }}>
          <span className="text-white text-[10px] font-medium">9:41</span>
        </div>
        {/* App bar */}
        <div className="h-12 flex items-center px-4 gap-2" style={{ backgroundColor: primaryColor }}>
          {iconPreview && (
            <img src={iconPreview} alt="icon" className="w-6 h-6 rounded" />
          )}
          <span className="text-white text-sm font-semibold truncate">
            {appName || 'My App'}
          </span>
        </div>
        {/* Content area */}
        <div className="p-4 space-y-3">
          <div className="h-3 rounded-full bg-gray-200 w-full" />
          <div className="h-3 rounded-full bg-gray-200 w-4/5" />
          <div className="h-20 rounded-lg bg-gray-100 mt-4" />
          <div className="h-3 rounded-full bg-gray-200 w-full" />
          <div className="h-3 rounded-full bg-gray-200 w-3/5" />
        </div>
        {/* Bottom nav */}
        <div className="absolute bottom-0 left-0 right-0 h-12 flex items-center justify-around" style={{ backgroundColor: secondaryColor }}>
          <div className="w-5 h-5 rounded bg-white/30" />
          <div className="w-5 h-5 rounded bg-white/30" />
          <div className="w-5 h-5 rounded bg-white/30" />
        </div>
      </div>
    </div>
  )
}

// ---------- Collapsible Section ----------

function CollapsibleSection({
  title,
  children,
  defaultOpen = false,
  helpUrl,
  helpLabel,
}: {
  title: string
  children: React.ReactNode
  defaultOpen?: boolean
  helpUrl?: string
  helpLabel?: string
}) {
  const [open, setOpen] = useState(defaultOpen)

  return (
    <div className="border rounded-xl overflow-hidden">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="flex items-center justify-between w-full px-5 py-4 bg-gray-50 hover:bg-gray-100 transition-colors"
      >
        <span className="font-medium text-gray-800">{title}</span>
        {open ? <ChevronUp className="w-5 h-5 text-gray-500" /> : <ChevronDown className="w-5 h-5 text-gray-500" />}
      </button>
      {open && (
        <div className="p-5 space-y-4">
          {helpUrl && (
            <a
              href={helpUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 text-sm text-blue-600 hover:text-blue-800 hover:underline"
            >
              <ExternalLink className="w-3.5 h-3.5" />
              {helpLabel || 'How to set this up?'}
            </a>
          )}
          {children}
        </div>
      )}
    </div>
  )
}

// ========== MAIN COMPONENT ==========

export default function CreateApp() {
  const navigate = useNavigate()
  const wizard = useWizardStore()
  const { step } = wizard

  useEffect(() => {
    return () => {
      useWizardStore.getState().reset()
    }
  }, [])

  const setStep = (s: number) => wizard.setStep(s)

  return (
    <div className="max-w-4xl mx-auto py-8 px-4">
      <h1 className="text-3xl font-bold text-gray-900 mb-2">Create New App</h1>
      <p className="text-gray-500 mb-8">Convert your website into a mobile app in minutes.</p>

      <StepIndicator currentStep={step} />

      <div className="bg-white rounded-2xl shadow-sm border p-4 sm:p-8">
        {step === 0 && <Step0BasicInfo />}
        {step === 1 && <Step1Visuals />}
        {step === 2 && <Step2Features />}
        {step === 3 && <Step3Advanced />}
        {step === 4 && <Step4PlanReview />}
      </div>
    </div>
  )
}

// ========== STEP 0 - BASIC INFO ==========

function Step0BasicInfo() {
  const wizard = useWizardStore()
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<BasicInfoData>({
    resolver: zodResolver(basicInfoSchema),
    defaultValues: {
      name: wizard.name,
      url: wizard.url,
      package_name: wizard.packageName,
      description: wizard.description,
    },
  })

  const createApp = useMutation({
    mutationFn: (data: BasicInfoData) =>
      appsApi.create({
        name: data.name,
        url: data.url,
        package_name: data.package_name || undefined,
        description: data.description || undefined,
        selected_platforms: wizard.selectedPlatforms,
      }),
    onSuccess: (res) => {
      wizard.setAppId(res.data.id)
      wizard.setBasicInfo({
        name: res.data.name,
        url: res.data.url,
        packageName: res.data.package_name || '',
        description: res.data.description || '',
      })
      wizard.setStep(1)
      toast.success('App created successfully')
    },
    onError: () => {
      toast.error('Failed to create app. Please try again.')
    },
  })

  const updateApp = useMutation({
    mutationFn: (data: BasicInfoData) =>
      appsApi.update(wizard.appId!, {
        name: data.name,
        url: data.url,
        package_name: data.package_name || undefined,
        description: data.description || undefined,
        selected_platforms: wizard.selectedPlatforms,
      }),
    onSuccess: (res) => {
      wizard.setBasicInfo({
        name: res.data.name,
        url: res.data.url,
        packageName: res.data.package_name || '',
        description: res.data.description || '',
      })
      wizard.setStep(1)
    },
    onError: () => {
      toast.error('Failed to update app.')
    },
  })

  const onSubmit = (data: BasicInfoData) => {
    if (wizard.appId) {
      updateApp.mutate(data)
    } else {
      createApp.mutate(data)
    }
  }

  const isLoading = createApp.isPending || updateApp.isPending
  const inputClass = 'w-full border rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent'

  const selectPlatform = (platform: Platform) => {
    wizard.setSelectedPlatforms([platform])
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
      {/* Platform Selector */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">Target Platform *</label>
        <p className="text-xs text-gray-500 mb-3">Select one platform at a time.</p>
        <div className="grid grid-cols-2 gap-4">
          <button
            type="button"
            onClick={() => selectPlatform('android')}
            className={`flex items-center gap-3 p-4 rounded-xl border-2 text-left transition-all ${
              wizard.selectedPlatforms.includes('android')
                ? 'border-blue-500 bg-blue-50'
                : 'border-gray-200 hover:border-gray-300 bg-white'
            }`}
          >
