          <input
            {...register('url')}
            className="w-full border-2 border-gray-300 rounded-xl pl-14 pr-5 py-3.5 text-base focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all hover:border-gray-400"
